const fs = require("node:fs");
const { createHash } = require("node:crypto");

const MAX_ISSUES = 3;
const TITLE_PREFIX = "[AI discovered CI] ";

function allObservations(dossier) {
  return [
    ...(dossier.pipelineHealth ?? []),
    ...(dossier.failures ?? []).flatMap(failure => failure.observations ?? [])
  ];
}

function errorMessageBlock(candidate) {
  return `## Error Message\n\n\`\`\`json\n${JSON.stringify({
    ErrorMessage: candidate.errorMessage,
    BuildRetry: candidate.buildRetry,
    ExcludeConsoleLog: candidate.excludeConsoleLog
  }, null, 2)}\n\`\`\``;
}

function withSignature(body, signature) {
  const hash = createHash("sha256").update(signature).digest("hex");
  const marker = `<!-- ci-quality-signature-sha256: ${hash} -->`;
  return body.includes("<!-- ci-quality-signature-sha256:") ? body : `${body.trim()}\n\n${marker}`;
}

function prepareOrdinaryIssue(item) {
  if (/^## Error Message\s*$/m.test(item.body)) {
    throw new Error("Ordinary CI issues must not contain a Build Analysis Error Message section.");
  }
  return {
    title: `${TITLE_PREFIX}${item.title}`,
    body: withSignature(item.body, item.signature),
    labels: ["agentic-workflows"]
  };
}

function prepareKbeIssue(item, observations) {
  const observation = observations.find(candidate => candidate.signature === item.signature);
  if (!observation || observation.kind !== "test" || !observation.kbe?.eligible
      || !observation.kbe.validation?.valid || !observation.kbe.recurring) {
    throw new Error(`KBE signature '${item.signature}' is not a recurring, collector-validated named test failure.`);
  }
  if (/^## Error Message\s*$/m.test(item.body)) {
    throw new Error("The KBE Error Message section is generated by the validator and must not be agent-authored.");
  }
  const body = `${item.body.trim()}\n\n${errorMessageBlock(observation.kbe)}`;
  return {
    title: `${TITLE_PREFIX}${item.title}`,
    body: withSignature(body, item.signature),
    labels: ["agentic-workflows", "Known Build Error"]
  };
}

function prepareIssues(agentOutput, dossier) {
  const items = (agentOutput.items ?? []).filter(item => item.type === "create_ci_quality_issue");
  if (items.length > MAX_ISSUES) throw new Error(`At most ${MAX_ISSUES} CI quality issues may be created per run.`);
  const observations = allObservations(dossier);
  return items.map(item => item.issue_kind === "test-kbe"
    ? prepareKbeIssue(item, observations)
    : prepareOrdinaryIssue(item));
}

async function issueExists(github, context, signatureHash) {
  const query = `repo:${context.repo.owner}/${context.repo.repo} is:issue in:body \"ci-quality-signature-sha256: ${signatureHash}\"`;
  const result = await github.rest.search.issuesAndPullRequests({ q: query, per_page: 1 });
  return result.data.total_count > 0;
}

async function applyIssue(issue, github, context, core, staged) {
  const signatureHash = issue.body.match(/<!-- ci-quality-signature-sha256: ([a-f0-9]{64}) -->/)?.[1];
  if (await issueExists(github, context, signatureHash)) {
    core.info(`Skipping existing CI quality issue for ${signatureHash}.`);
    return;
  }
  if (staged) {
    await core.summary.addHeading(`Staged issue: ${issue.title}`, 3)
      .addRaw(`Labels: ${issue.labels.join(", ")}\n\n${issue.body}\n`).write();
    return;
  }
  await github.rest.issues.create({ ...context.repo, ...issue });
}

async function main({ core, github, context }) {
  const agentOutput = JSON.parse(fs.readFileSync(process.env.GH_AW_AGENT_OUTPUT, "utf8"));
  const dossier = JSON.parse(fs.readFileSync(process.env.CI_QUALITY_DOSSIER_PATH, "utf8"));
  const issues = prepareIssues(agentOutput, dossier);
  for (const issue of issues) {
    await applyIssue(issue, github, context, core, process.env.GH_AW_SAFE_OUTPUTS_STAGED === "true");
  }
}

module.exports = { main, prepareIssues };